@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,500;0,600;0,700;0,800;1,600;1,700&display=swap');
:root{--ink:#f7ecdb;--muted:#c0a993;--gold:#e4b66f;--rust:#bb6b49;--dark:#241915;--panel:rgba(38,27,23,.91);--line:rgba(246,219,182,.19)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#241915;color:var(--ink);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit}.game-shell{position:relative;width:100%;height:100%;min-height:540px;overflow:hidden;background:#936b58}#world{position:absolute;inset:0;background:linear-gradient(180deg,#bd7b68 0%,#e0a16d 37%,#d19a63 52%,#785543 100%)}#world canvas{display:block;width:100%;height:100%}.world-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(33,22,20,.32) 0%,transparent 18%,transparent 55%,rgba(27,18,16,.22) 100%),linear-gradient(90deg,rgba(27,19,17,.22),transparent 25%,transparent 75%,rgba(27,19,17,.16));z-index:1}.topbar{position:absolute;z-index:5;left:0;right:0;top:0;height:78px;padding:0 40px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,239,217,.13);background:linear-gradient(180deg,rgba(37,25,22,.58),rgba(37,25,22,0))}.wordmark{display:flex;align-items:center;gap:11px;color:#fff4e3;text-decoration:none;font-weight:700;font-size:13px;letter-spacing:2.1px}.wordmark i{font-family:'Playfair Display',serif;color:var(--gold);font-size:17px}.brand-mark{color:var(--gold);font-size:23px}.day-pill{font-size:10px;letter-spacing:1.55px;font-weight:600;color:#f8dfc0;border:1px solid rgba(255,238,215,.27);background:rgba(36,25,21,.27);padding:10px 15px;border-radius:20px}.sun-icon{font-size:15px;color:#edc787;margin-right:8px}.sound-button{border:0;background:transparent;color:#fae8d0;letter-spacing:1.5px;font-size:10px;cursor:pointer;opacity:.85}.sound-button:first-letter{font-size:17px;color:var(--gold)}.scene-label{position:absolute;z-index:3;top:99px;left:40px;color:#f4dfc5;font-size:10px;letter-spacing:1.7px;text-transform:uppercase;text-shadow:0 1px 5px #422b23}.live-dot{display:inline-block;width:6px;height:6px;background:#d9b677;border-radius:50%;margin:0 9px 1px 0;box-shadow:0 0 9px #f4c778}.intro-card{position:absolute;z-index:4;left:8.2%;top:23%;width:min(440px,40vw);padding:34px 36px 29px;background:linear-gradient(140deg,rgba(43,29,25,.89),rgba(43,29,25,.74));border:1px solid rgba(248,222,184,.32);box-shadow:0 20px 70px rgba(32,18,13,.22);backdrop-filter:blur(11px);animation:fadeup .9s ease both}.eyebrow{font-size:9px;font-weight:700;letter-spacing:2px;color:#e5b977}.eyebrow span{padding:0 4px}.intro-card h1{font-family:'Playfair Display',serif;font-size:clamp(40px,5vw,63px);line-height:.98;font-weight:600;letter-spacing:-1.6px;margin:17px 0 15px;color:#fff3e1}.intro-card h1 em{color:#e8bc7d;font-weight:500}.intro-card p{color:#d4beaa;font-size:13px;line-height:1.75;max-width:348px;margin:0 0 22px}.intro-meta{display:flex;gap:13px;padding:14px 0 17px;border-top:1px solid var(--line);font-size:8px;letter-spacing:1px;color:#c5a98e;white-space:nowrap}.primary-button{display:flex;align-items:center;justify-content:space-between;width:100%;padding:14px 17px;background:#c47b52;border:0;color:#fff7e9;font-size:10px;font-weight:700;letter-spacing:1.8px;cursor:pointer;transition:background .2s,transform .2s}.primary-button:hover{background:#d18c5d;transform:translateY(-2px)}.primary-button span{font-size:17px}.mature-note{font-size:9px;color:#a88f7d;text-align:center;margin-top:13px}.cast-panel{position:absolute;z-index:4;right:39px;top:24%;width:260px;padding:18px 17px 12px;background:rgba(37,26,22,.77);border:1px solid rgba(248,222,184,.2);backdrop-filter:blur(8px);box-shadow:0 12px 45px rgba(35,21,15,.2);transition:opacity .3s,transform .3s}.cast-heading{display:flex;justify-content:space-between;font-size:9px;letter-spacing:1.8px;color:#e4c59f;font-weight:700;padding:0 2px 12px}.cast-count{color:#a9907a}.character-card{border:0;border-top:1px solid rgba(255,238,215,.12);background:transparent;width:100%;display:flex;align-items:center;text-align:left;padding:10px 1px;cursor:pointer;gap:10px;transition:background .2s}.character-card:hover{background:rgba(255,230,190,.08)}.portrait{width:37px;height:37px;border-radius:50%;display:grid;place-items:center;flex:none;border:1px solid rgba(255,237,204,.45);font-size:17px}.portrait-ada{background:radial-gradient(circle at 50% 32%,#ddaf87 0 22%,#54342e 23% 43%,#201c20 44% 100%);color:#e9c28d}.portrait-cleo{background:radial-gradient(circle at 50% 32%,#e4b89a 0 22%,#5f5545 23% 44%,#253b39 45% 100%);color:#d8b27b}.portrait-ruby{background:radial-gradient(circle at 50% 32%,#eac39e 0 22%,#8c4c49 23% 44%,#422837 45% 100%);color:#f1ce9b}.character-copy{display:flex;flex-direction:column;gap:4px;min-width:0}.character-copy strong{font-family:'Playfair Display',serif;font-weight:600;font-size:13px;color:#fff0dd;white-space:nowrap}.character-copy small{font-size:8px;color:#b99c82;letter-spacing:1.1px}.card-arrow{margin-left:auto;color:#cf9f69;font-size:14px}.cast-foot{border-top:1px solid rgba(255,238,215,.12);margin-top:4px;padding-top:12px;color:#ad927a;font-size:9px}.cast-foot span{color:#d7907b;margin-right:5px}.location-nav{position:absolute;z-index:4;bottom:38px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:5px;padding:8px;background:rgba(35,24,21,.78);border:1px solid rgba(246,219,182,.2);backdrop-filter:blur(8px)}.nav-caption{font-size:8px;letter-spacing:1.5px;color:#bb9c7d;padding:0 12px 0 8px;white-space:nowrap}.location-button{border:1px solid transparent;background:transparent;display:flex;align-items:center;gap:7px;padding:9px 11px;cursor:pointer;color:#d4b99e;transition:all .2s}.location-button span{font-size:15px}.location-button small{font-size:8px;letter-spacing:1px;white-space:nowrap}.location-button:hover,.location-button.active{background:rgba(198,132,82,.2);border-color:rgba(230,183,120,.35);color:#f4d4a9}.dialogue-wrap{position:absolute;z-index:6;left:50%;bottom:24px;transform:translateX(-50%);width:min(770px,67vw);animation:fadeup .45s ease both}.dialogue-wrap.hidden{display:none}.dialogue-topline{display:flex;align-items:center;justify-content:space-between;color:#efc78e;font-size:8px;letter-spacing:1.7px;font-weight:700;margin-bottom:8px}.dialogue-progress{height:2px;width:96px;background:rgba(255,242,222,.25);display:block}.dialogue-progress i{height:100%;display:block;width:22%;background:#e8bb7a;transition:width .3s}.dialogue-box{background:rgba(38,27,23,.95);border:1px solid rgba(247,220,181,.34);box-shadow:0 14px 50px rgba(22,14,11,.4);padding:21px 26px 19px;backdrop-filter:blur(12px)}.speaker-row{display:flex;align-items:center;gap:11px}.speaker-icon{width:35px;height:35px;border-radius:50%;display:grid;place-items:center;background:#63473a;color:#ecc78e;border:1px solid rgba(245,214,171,.45);font-size:17px}.speaker-name{font-family:'Playfair Display',serif;font-size:17px;font-weight:600;color:#fff0dc}.speaker-role{font-size:8px;letter-spacing:1.4px;color:#bd9d7d;margin-top:3px}.affection{margin-left:auto;font-size:13px;color:#e79583}.affection span{color:#f1d0a6;font-size:10px}.dialogue-box p{font-family:'Playfair Display',serif;font-size:17px;line-height:1.55;color:#f1e1ce;margin:15px 0 17px;max-width:700px}.choice-list{display:grid;grid-template-columns:1fr 1fr;gap:8px}.choice-button{border:1px solid rgba(247,220,181,.24);background:rgba(255,238,215,.045);padding:11px 13px;text-align:left;color:#e7d2bb;cursor:pointer;font-size:11px;line-height:1.4;transition:all .2s}.choice-button:hover{border-color:#d6a86f;background:rgba(210,160,103,.14);color:#fff3e2}.choice-button .choice-num{color:#d4a66f;font-size:9px;letter-spacing:1px;margin-right:8px}.continue-button{border:0;background:transparent;color:#ecc38b;font-size:9px;font-weight:700;letter-spacing:1.7px;cursor:pointer;padding:9px 0 0;float:right}.continue-button span{font-size:15px;margin-left:8px}.bottom-note{position:absolute;z-index:3;bottom:10px;left:40px;right:40px;display:flex;justify-content:space-between;color:rgba(255,231,200,.55);font-size:8px;letter-spacing:1.7px;pointer-events:none}.loading{position:absolute;inset:0;z-index:10;display:flex;align-items:center;justify-content:center;gap:13px;background:#34251f;color:#e6c08e;letter-spacing:2px;font-size:10px;transition:opacity .7s}.loading.done{opacity:0;pointer-events:none}.loader-star{font-size:21px;animation:spin 3s linear infinite}.toast{position:absolute;z-index:9;left:50%;top:17%;transform:translate(-50%,-10px);padding:11px 18px;background:rgba(40,27,22,.92);border:1px solid rgba(236,192,132,.36);color:#f0d1a7;font-size:11px;letter-spacing:.3px;opacity:0;transition:all .25s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}@keyframes fadeup{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}@keyframes spin{to{transform:rotate(360deg)}}
@media(max-width:900px){.topbar{padding:0 22px}.intro-card{left:5%;top:22%;width:45vw;padding:26px}.cast-panel{right:20px;width:230px;top:27%}.intro-card h1{font-size:48px}.scene-label{left:22px}.dialogue-wrap{width:80vw}.bottom-note{left:22px;right:22px}}@media(max-width:650px){.game-shell{min-height:600px}.topbar{height:62px;padding:0 16px}.wordmark{font-size:10px;letter-spacing:1.4px;gap:7px}.brand-mark{font-size:19px}.day-pill{font-size:7px;padding:8px}.sun-icon{margin-right:4px}.sound-button{font-size:0}.sound-button:first-letter{font-size:19px}.scene-label{top:73px;left:16px;font-size:8px}.intro-card{left:5%;top:15%;width:90%;padding:22px 22px 18px}.intro-card h1{font-size:42px;margin:11px 0}.intro-card p{font-size:11px;line-height:1.55;margin-bottom:12px}.intro-meta{font-size:7px;gap:8px;padding:10px 0}.primary-button{padding:12px 14px}.mature-note{font-size:8px;margin-top:9px}.cast-panel{top:auto;bottom:120px;right:5%;width:90%;padding:9px 12px}.cast-heading{padding-bottom:6px}.character-card{padding:6px 1px;gap:8px}.portrait{width:30px;height:30px;font-size:14px}.character-copy strong{font-size:12px}.character-copy small{font-size:7px}.cast-foot{display:none}.location-nav{bottom:28px;width:92%;justify-content:center;gap:1px;padding:5px}.nav-caption{display:none}.location-button{padding:9px 7px;gap:4px}.location-button small{font-size:7px}.location-button span{font-size:13px}.dialogue-wrap{width:92vw;bottom:12px}.dialogue-box{padding:15px 16px 13px}.dialogue-topline{font-size:7px}.dialogue-progress{width:64px}.speaker-icon{width:30px;height:30px}.speaker-name{font-size:15px}.dialogue-box p{font-size:15px;margin:11px 0 12px}.choice-list{grid-template-columns:1fr;gap:6px;max-height:34vh;overflow:auto}.choice-button{padding:9px 10px;font-size:10px}.location-nav.dialogue-open{display:none}.bottom-note{bottom:8px;font-size:6px;left:15px;right:15px}.dialogue-wrap~.bottom-note{display:none}}

import * as THREE from 'three';

const mat=(color,roughness=1)=>new THREE.MeshStandardMaterial({color,roughness});
const palette={wood:'#79513b',wood2:'#966344',dark:'#392a25',cream:'#ead8b9',roof:'#49312b',sand:'#b8875b',rust:'#b96248',sage:'#65715a',gold:'#dda96a'};
function box(parent,x,y,z,w,h,d,color,opts={}){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat(color));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function sphere(parent,x,y,z,r,color,sx=1,sy=1,sz=1){const m=new THREE.Mesh(new THREE.SphereGeometry(r,16,12),mat(color));m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;parent.add(m);return m}
function cylinder(parent,x,y,z,r1,r2,h,color,segments=12){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),mat(color));m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m}
function makeBuilding(parent,x,z,w,h,d,color,front=true){const g=new THREE.Group();g.position.set(x,0,z);parent.add(g);box(g,0,h/2,0,w,h,d,color);box(g,0,h+.25,0,w+.28,.5,d+.28,palette.roof);for(let i=-1;i<=1;i++){box(g,i*w*.27,h*.56,d/2+.012,.42,.67,.06,'#34251f');box(g,i*w*.27,h*.56,d/2+.05,.05,.73,.05,'#b18a60')}box(g,0,h+.12,d/2+.04,w+.18,.16,.14,'#c7a576');box(g,0,h*.23,d/2+.05,.9,h*.46,.12,'#473128');if(front){box(g,0,h+.62,d/2+.16,2.1,.55,.13,'#392820');box(g,0,h+.62,d/2+.24,1.96,.06,.02,'#dfba83')}return g}
function makePerson(parent, cfg){const g=new THREE.Group();g.position.set(cfg.x,0,cfg.z);parent.add(g);const skin=cfg.skin||'#d79a77', outfit=cfg.outfit, hair=cfg.hair;
 sphere(g,0,1.54,0,.32,skin,.82,1.05,.8);sphere(g,0,1.68,-.08,.34,hair,.94,.87,.92);sphere(g,-.31,1.48,0,.1,skin,.6,1,.65);sphere(g,.31,1.48,0,.1,skin,.6,1,.65);
 // torso, skirt, sleeves and boots
 const torso=cylinder(g,0,.94,0,.38,.28,.8,outfit,10);torso.scale.x=.9;const skirt=cylinder(g,0,.48,0,.55,.3,.62,cfg.skirt||outfit,12);skirt.position.y=.48;
 cylinder(g,-.39,.95,0,.13,.14,.67,outfit,10).rotation.z=.22;cylinder(g,.39,.95,0,.14,.13,.67,outfit,10).rotation.z=-.22;
 box(g,-.16,.13,.04,.22,.28,.34,'#35251f');box(g,.16,.13,.04,.22,.28,.34,'#35251f');
 // eyes and smile
 sphere(g,-.105,1.56,.277,.035,'#2b211e',1,.65,.45);sphere(g,.105,1.56,.277,.035,'#2b211e',1,.65,.45);box(g,0,1.39,.286,.11,.025,.02,'#a85e58');
 if(cfg.hat){cylinder(g,0,1.92,0,.42,.42,.07,cfg.hat,16);cylinder(g,0,2.07,0,.25,.27,.25,cfg.hat,12);box(g,0,1.96,.03,.35,.045,.36,cfg.band||palette.gold)}
 if(cfg.accent){box(g,.12,1.03,.28,.07,.07,.025,cfg.accent)}
 g.userData.baseY=0;return g}

export class WesternScene{
 constructor(el){this.el=el;this.scene=new THREE.Scene();this.scene.background=new THREE.Color('#c9836f');this.scene.fog=new THREE.Fog('#c9836f',24,73);this.camera=new THREE.PerspectiveCamera(42,1,.1,120);this.camera.position.set(0,7.3,18);this.camera.lookAt(0,1.8,0);this.renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});this.renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=THREE.PCFSoftShadowMap;this.renderer.toneMapping=THREE.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.28;el.appendChild(this.renderer.domElement);this.clock=new THREE.Clock();this.characters={};this.location='town';this.makeWorld();this.resize();window.addEventListener('resize',()=>this.resize());this.animate()}
 makeWorld(){const s=this.scene;const hemi=new THREE.HemisphereLight('#ffe3c4','#604333',2.1);s.add(hemi);const sun=new THREE.DirectionalLight('#ffd29a',3);sun.position.set(-8,14,9);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);s.add(sun);const fill=new THREE.DirectionalLight('#da9da4',.8);fill.position.set(9,8,-8);s.add(fill);
 const ground= new THREE.Mesh(new THREE.PlaneGeometry(120,100),mat('#aa7954'));ground.rotation.x=-Math.PI/2;ground.position.y=-.06;ground.receiveShadow=true;s.add(ground);
 // mesa silhouettes and distant buttes
 for(let i=0;i<9;i++){const x=(i-4)*9;const h=2.2+(i*7%5)*.62;const m=new THREE.Mesh(new THREE.ConeGeometry(4.5+(i%3)*1.5,h,5),mat(i%2?'#9b6155':'#a96758'));m.position.set(x,h/2-1,-31-(i%3)*4);m.rotation.y=.35;s.add(m)}
 // dirt road across the town
 const road=new THREE.Mesh(new THREE.PlaneGeometry(14,100),mat('#c49365'));road.rotation.x=-Math.PI/2;road.rotation.z=Math.PI/2;road.position.set(0,.01,-10);road.receiveShadow=true;s.add(road);
 // boardwalks and buildings
 for(const side of [-1,1]){box(s,side*7.2,.19,-3.3,3.8,.35,22,'#674532');for(let i=0;i<5;i++){const z=-10+i*4.9;makeBuilding(s,side*(9.4+(i%2)*1.2),z,4.2,3.3+(i%3)*.35,3.2,i%2?'#a16a49':'#7d5540');}}
 // recognizable saloon with porch and swinging sign
 const saloon=makeBuilding(s,-4.8,-1,5.1,4,4.3,'#9b6447');box(s,-4.8,2.5,1.3,5.8,.16,.4,'#c89e6c');for(let x of [-7,-2.6])cylinder(s,x,1.1,1.38,.075,.075,2.2,'#67422f');box(s,-4.8,3.5,1.51,2.1,.53,.17,'#372720');box(s,-4.8,3.52,1.61,1.92,.055,.02,'#efca8e');
 // water tower and windmill
 cylinder(s,7,3.1,-13,1.35,1.15,2.2,'#704e3a',16);cylinder(s,7,4.25,-13,1.55,1.55,.18,'#c09162',16);for(let i=0;i<4;i++){const blade=box(s,7,5.2,-13, .11,1.7,.1,'#d7c09a');blade.rotation.z=i*Math.PI/2}
 // cacti and scrub along the outskirts
 for(const [x,z] of [[-12,-12],[-14,-4],[13,-7],[12,2],[-13,3],[15,-18]]){cylinder(s,x,.8,z,.2,.24,1.6,'#526347',8);cylinder(s,x-.28,.65,z,.11,.13,.6,'#526347',8).rotation.z=1.2;cylinder(s,x-.5,.8,z,.1,.11,.45,'#526347',8);cylinder(s,x+.29,1.05,z,.11,.13,.6,'#526347',8).rotation.z=-1.2;cylinder(s,x+.49,1.19,z,.1,.11,.38,'#526347',8)}
 // foreground hitching rail, barrels, hay
 for(let i=0;i<3;i++){cylinder(s,-8+i*1.1,.45,4,.34,.34,.9,i===1?'#9a6543':'#85563d',12);cylinder(s,-8+i*1.1,.93,4,.35,.35,.08,'#b48a5f',12)}box(s,5,.85,3,3,.12,.12,'#674b36');for(let x of [3.7,6.3])box(s,x,.42,3,.12,.85,.12,'#674b36');
 // suspended dust sparkles
 this.dust=[];for(let i=0;i<42;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(.025+(i%3)*.012,6,6),new THREE.MeshBasicMaterial({color:i%4?'#ffe0a6':'#fff0c8',transparent:true,opacity:.35+Math.random()*.4}));m.position.set((Math.random()-.5)*24,Math.random()*5+.2,(Math.random()-.5)*20-2);m.userData.phase=Math.random()*6;s.add(m);this.dust.push(m)}
 this.characters.ada=makePerson(s,{x:-3.3,z:2.2,skin:'#cf9778',outfit:'#47383a',skirt:'#332b31',hair:'#251d20',hat:'#392d2b',band:'#bf744e',accent:'#deb375'});
 this.characters.cleo=makePerson(s,{x:0,z:1.9,skin:'#e0b08e',outfit:'#48625b',skirt:'#3f5149',hair:'#a5734e',hat:'#766144',band:'#dfb56e',accent:'#b5c29a'});
 this.characters.ruby=makePerson(s,{x:3.4,z:2.2,skin:'#dca07c',outfit:'#8b4e56',skirt:'#683d4b',hair:'#39232a',hat:'#6b3735',band:'#e5b176',accent:'#e5bd79'});
 // scale and individually pose the three women as a welcoming cast
 for(const [key,g] of Object.entries(this.characters)){g.scale.setScalar(.9);g.userData.phase=Object.keys(this.characters).indexOf(key)*1.9;}
 this.showCharacter(null);
 // sunset disc
 const sunDisc=new THREE.Mesh(new THREE.CircleGeometry(2.1,40),new THREE.MeshBasicMaterial({color:'#f8c17f'}));sunDisc.position.set(-12,10,-34);sunDisc.lookAt(this.camera.position);s.add(sunDisc);
 }
 showCharacter(key){for(const [id,g] of Object.entries(this.characters)){g.visible=!key||key===id;g.scale.setScalar(key===id?1.12:.9)}}
 setLocation(location){this.location=location;const goals={town:{x:0,y:7.3,z:18,lookX:0,lookY:1.8,lookZ:0},saloon:{x:-2.1,y:5.7,z:11,lookX:-4,lookY:1.4,lookZ:0},canyon:{x:0,y:8.5,z:20,lookX:0,lookY:1.6,lookZ:-7}};this.goal=goals[location]}
 resize(){const w=this.el.clientWidth||innerWidth,h=this.el.clientHeight||innerHeight;this.camera.aspect=w/h;this.camera.updateProjectionMatrix();this.renderer.setSize(w,h)}
 animate(){requestAnimationFrame(()=>this.animate());const t=this.clock.getElapsedTime();this.dust.forEach((m,i)=>{m.position.y+=Math.sin(t*.5+m.userData.phase)*.0015;m.position.x+=Math.sin(t*.28+i)*.001});for(const g of Object.values(this.characters)){g.position.y=Math.sin(t*1.3+g.userData.phase)*.025;g.rotation.y=Math.sin(t*.42+g.userData.phase)*.035}if(this.goal){this.camera.position.lerp(new THREE.Vector3(this.goal.x,this.goal.y,this.goal.z),.025);this.camera.lookAt(new THREE.Vector3(this.goal.lookX,this.goal.lookY,this.goal.lookZ));if(this.camera.position.distanceTo(new THREE.Vector3(this.goal.x,this.goal.y,this.goal.z))<.04)this.goal=null}this.renderer.render(this.scene,this.camera)}
}

import { WesternScene } from './scene.js';

const cast={
 ada:{name:'Ada Vale',role:'THE OUTLAW',icon:'✦',chapter:'CHAPTER ONE · THE MOST WANTED HEART',
  scenes:[
   {text:'A woman in a weather-beaten hat leans against the hitching rail. A wanted poster peeks from her coat. “You’re the new girl. I was hoping you’d be pretty. How fortunate for both of us.”',choices:[['“And I was hoping the infamous Ada Vale would be taller.”',2,'Her laugh is low and delighted. “Oh, you’re trouble. I can tell.”'],['“You’ve been hoping to meet me?”',1,'“Since the train came over the ridge,” she admits, then tips her hat.'],['“Should I be worried about that poster?”',0,'“Only if you’re planning to turn me in.” Her smile says she hopes you aren’t.']]},
   {text:'Ada invites you to ride out to Red Rock Pass. The sun burns orange along the canyon rim. She keeps glancing at you instead of the trail.',choices:[['“Tell me what you’re running toward, not away from.”',2,'For once, Ada has no quick answer. Then she tells you about the ranch she dreams of.'],['Race you to that ridge. Loser buys supper.',1,'She whoops, and the two of you gallop beneath the wide-open sky.'],['“You always ride with a hand near your holster?”',0,'“Only when I’m nervous.” She catches your eye. “Don’t look so pleased.”']]},
   {text:'At the canyon overlook, Ada takes off her hat. “I could leave town tonight. But truth is, there’s something here I’d miss.” She looks straight at you.',choices:[['“Stay. We can figure out what comes next together.”',2,'The guarded look in Ada’s eyes gives way to something achingly hopeful.'],['“You don’t have to decide tonight.”',1,'“That’s the kindest thing anyone’s said to me in years.”'],['“I’m not a reason to give up your freedom.”',0,'“No,” she agrees softly. “You’re the first person who’s understood that.”']]},
   {text:'Under the stars, Ada offers you her hand. No guns, no getaway plan—just an invitation to see where tomorrow goes.',choices:[['Take her hand. “Let’s make a little trouble, together.”',2,'“My favorite kind,” Ada whispers, leaning her forehead against yours.'],['“One sunrise at a time?”',1,'“One sunrise at a time.” Her thumb brushes yours.'],['“I want you, but I want you to choose this for yourself.”',1,'Ada smiles, tender and certain. “I am. I choose you.”']]}
  ],endings:[
   ['THE WILD HORIZON','Together, you and Ada bought a forgotten ranch beyond the pass. She still rides too fast and laughs too loud. Every evening, she comes home to you—her favorite place to stay.'],
   ['A PROMISE AT SUNSET','Ada kissed you beneath the canyon stars, then asked if she could court you properly. You said yes. Some wild hearts don’t need taming; they just need someone to ride beside them.']
  ]},
 cleo:{name:'Clementine “Cleo” Bell',role:'THE INVENTOR',icon:'⚙',chapter:'CHAPTER TWO · A SPARK IN THE DUST',
  scenes:[
   {text:'A burst of steam erupts from the telegraph office. A woman in oil-stained overalls emerges, goggles perched on her auburn curls. “Perfect timing! I need someone charming to test my new talking machine.”',choices:[['“I’m charming. How dangerous is the machine?”',2,'“Only to people who dislike surprises!” Cleo beams. “So, fairly safe.”'],['“Does it talk back, or just listen?”',1,'“I’ve been working on the listening part.” Her grin softens.'],['“Maybe we should test it on a cactus first.”',0,'“The cactus has already filed a complaint.” She looks at you hopefully.']]},
   {text:'Her workshop is a cathedral of gears, glass bottles and brilliant ideas. Cleo describes the invention she’s spent years building—then goes quiet.',choices:[['“What would you make if nobody could tell you it was impractical?”',2,'Cleo’s eyes light up. She sketches a little flying machine meant to carry letters to lonely places.'],['“Show me the one you’re proudest of.”',1,'She demonstrates a wind-up bird that chirps a surprisingly sweet tune.'],['“You made all of this by yourself?”',0,'“Mostly.” The answer sounds lonelier than she meant it to.']]},
   {text:'The talking machine finally crackles to life. A voice says: “Cleo, you deserve someone who sees you.” She laughs nervously and looks at you.',choices:[['“It’s right. And I see a woman I’d be lucky to know.”',2,'Cleo blushes all the way to her ears. “That’s a remarkably good first impression.”'],['“Does the machine always have such excellent timing?”',1,'“It’s very perceptive. Or I may have told it a few things.”'],['“You deserve that whether or not you invent anything.”',1,'Her shoulders relax. “I think I needed to hear that.”']]},
   {text:'Cleo invites you to the roof to watch the stars. A brass telescope points skyward; her hand finds yours beside it.',choices:[['“Let’s build a life with room for all your impossible ideas.”',2,'“And a little room for you?” she asks. “A lot of room,” you promise.'],['“Show me the star you named after your first invention.”',1,'Cleo points out a bright star and tells you a story that lasts until midnight.'],['“Can I kiss you?”',1,'“Please,” Cleo says, leaning in with a breathless smile.']]}
  ],endings:[
   ['THE BRIGHTER TOMORROW','Cleo’s inventions began carrying letters across the territory. Your home became her workshop, your porch became a launchpad—and no matter how far her ideas flew, she always came back to you.'],
   ['A LITTLE SPARK','Cleo kissed you beneath the observatory stars. It was sweet, a little clumsy, and the beginning of something you both wanted to discover at your own pace.']
  ]},
 ruby:{name:'Ruby Sol',role:'THE SONGBIRD',icon:'♫',chapter:'CHAPTER THREE · A SONG FOR TWO',
  scenes:[
   {text:'The Starling Saloon falls quiet as a velvet-voiced singer steps into the lamplight. After her last note, Ruby spots you at the bar. “That applause was lovely. Yours was my favorite.”',choices:[['“I think my heart applauded, too.”',2,'Ruby laughs, delighted. “Then I’ll have to sing for it again.”'],['“You make this place feel like somewhere to belong.”',1,'She looks at you with real warmth. “That’s the nicest review I’ve had.”'],['“Do you ever sing somewhere besides the saloon?”',0,'“I sing wherever someone is willing to listen.” Her gaze lingers on you.']]},
   {text:'Ruby walks you along the lantern-lit boardwalk. She tells you she wants to write a song that belongs to her—not the saloon, not the town. Her voice falters.',choices:[['“Let me hear the unfinished version.”',2,'She sings you a trembling verse. It’s beautiful precisely because it isn’t finished.'],['“What would you want the last line to say?”',1,'“That I got to choose my own ending,” Ruby says, thinking out loud.'],['“You could leave town, if you wanted.”',0,'“I could,” she says. “But I don’t want to run from my life. I want to make it mine.”']]},
   {text:'A piano waits in the empty saloon. Ruby plays a new melody, then turns on the stool. “I wrote this after you came to town. Is that too much?”',choices:[['“It’s a lovely song. And I’m glad I inspired it.”',2,'Ruby exhales, a smile breaking across her face. “I was hoping you’d say that.”'],['“You can feel a lot without asking me to carry it for you.”',1,'“Exactly.” She smiles, grateful. “I like that you understand the difference.”'],['“Only if you promise not to write me a tragic ending.”',1,'“No promises,” she teases. “But I’ll make the last verse happy.”']]},
   {text:'Ruby offers you a place beside her at the piano. She doesn’t ask for forever—just a dance, and an honest answer about what you want.',choices:[['“I want to choose you, in every verse.”',2,'Ruby rests her forehead against yours. “Then let’s write this song together.”'],['“I want to see where the next verse takes us.”',1,'“That’s my favorite kind of promise.” She takes your hand.'],['“I want to keep hearing you sing. Can we start there?”',1,'“We can start anywhere,” Ruby says. “As long as we start honestly.”']]}
  ],endings:[
   ['THE SONG YOU SHARE','Ruby’s song traveled from Coyote Creek clear to Santa Fe. She sang it for crowded halls and quiet mornings at home. In every version, the sweetest note was the one she saved just for you.'],
   ['THE FIRST VERSE','Ruby kissed you by the old piano, then asked you to stay for one more song. You did. The rest of the melody could wait until tomorrow.']
  ]}
};

const scene=new WesternScene(document.querySelector('#world'));
const $=s=>document.querySelector(s);
const intro=$('#intro-card'),castPanel=$('#cast-panel'),dialogue=$('#dialogue-wrap'),choices=$('#choice-list'),continueButton=$('#continue-button');
let started=false, active=null, step=0, affection=0, chosenLocation='town', hasPicked=false, soundOn=false;
const locationNames={town:'Coyote Creek, Arizona Territory',saloon:'The Starling Saloon',canyon:'Red Rock Pass'};
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2100)}
function start(){if(started)return;started=true;intro.classList.add('hidden');$('#location-nav').classList.add('visible');toast('Welcome to Coyote Creek. The frontier is yours to explore.');}
function startRoute(id){if(!started)start();active=id;step=0;affection=0;hasPicked=false;scene.showCharacter(id);dialogue.classList.remove('hidden');castPanel.classList.add('muted');$('#location-nav').classList.add('dialogue-open');$('#chapter-label').textContent=cast[id].chapter;renderScene();}
function renderScene(){const person=cast[active],story=person.scenes[step];$('#speaker-name').textContent=person.name;$('#speaker-role').textContent=person.role;$('#speaker-icon').textContent=person.icon;$('#affection span').textContent=affection;$('#progress-fill').style.width=`${((step+1)/person.scenes.length)*100}%`;$('#dialogue-text').textContent=story.text;choices.innerHTML='';continueButton.classList.add('hidden');hasPicked=false;story.choices.forEach(([label,score,response],i)=>{const b=document.createElement('button');b.className='choice-button';b.innerHTML=`<span class="choice-num">0${i+1}</span>${label}`;b.addEventListener('click',()=>choose(score,response,b));choices.appendChild(b)});}
function choose(score,response,button){if(hasPicked)return;hasPicked=true;affection+=score;$('#affection span').textContent=affection;$('#dialogue-text').textContent=response;choices.innerHTML='';continueButton.classList.remove('hidden');if(score>=2)toast('A spark of affection ✦');}
function finishRoute(){const person=cast[active],ending=person.endings[affection>=6?0:1];$('#chapter-label').textContent='YOUR STORY · AN ENDING';$('#progress-fill').style.width='100%';$('#speaker-name').textContent=ending[0];$('#speaker-role').textContent=`${person.name.toUpperCase()} · YOUR FRONTIER ENDING`;
 $('#speaker-icon').textContent=person.icon;$('#affection span').textContent=affection;$('#dialogue-text').textContent=ending[1];choices.innerHTML='';const replay=document.createElement('button');replay.className='choice-button';replay.innerHTML='<span class="choice-num">↻</span>Take another ride with her';replay.onclick=()=>startRoute(active);const other=document.createElement('button');other.className='choice-button';other.innerHTML='<span class="choice-num">✦</span>Meet someone else';other.onclick=()=>{dialogue.classList.add('hidden');castPanel.classList.remove('muted');scene.showCharacter(null);$('#location-nav').classList.remove('dialogue-open');toast('Choose your next adventure.')};choices.append(replay,other);continueButton.classList.add('hidden');}
continueButton.addEventListener('click',()=>{if(step<cast[active].scenes.length-1){step++;renderScene()}else finishRoute()});
$('#begin-button').addEventListener('click',start);
document.querySelectorAll('.character-card').forEach(button=>button.addEventListener('click',()=>startRoute(button.dataset.character)));
document.querySelectorAll('.location-button').forEach(button=>button.addEventListener('click',()=>{const loc=button.dataset.location;chosenLocation=loc;scene.setLocation(loc);document.querySelectorAll('.location-button').forEach(b=>b.classList.toggle('active',b===button));$('#place-label').textContent=locationNames[loc];if(loc==='saloon')toast('Warm lamplight spills from The Starling.');else if(loc==='canyon')toast('The red cliffs glow in the last of the sun.');else toast('A little dust, a lot of possibility.')}));
$('#sound-toggle').addEventListener('click',()=>{soundOn=!soundOn;$('#sound-toggle').innerHTML=soundOn?'♫ <span>AMBIENCE ON</span>':'♫ <span>AMBIENCE</span>';toast(soundOn?'Sound toggle is ready for the next campfire tune.':'Ambient sound off.')});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&active){dialogue.classList.add('hidden');castPanel.classList.remove('muted');scene.showCharacter(null);$('#location-nav').classList.remove('dialogue-open');active=null}else if(e.key==='Enter'&&!dialogue.classList.contains('hidden')&&!continueButton.classList.contains('hidden'))continueButton.click()});
scene.setLocation('town');
setTimeout(()=>$('#loading').classList.add('done'),800);

