splay:inline-block;width:6px;height:6px;background:#d9b677;border-radius:50%;margin:0 9px 1px 0;box-shadow:0 0 9px #f4c778}.intro-card{position:absolute;z-index:4;left:8.2%;top:23%;width:min(440px,40vw);padding:34px 36px 29px;background:linear-gradient(140deg,rgba(43,29,25,.89),rgba(43,29,25,.74));border:1px solid rgba(248,222,184,.32);box-shadow:0 20px 70px rgba(32,18,13,.22);backdrop-filter:blur(11px);animation:fadeup .9s ease both}.eyebrow{font-size:9px;font-weight:700;letter-spacing:2px;color:#e5b977}.eyebrow span{padding:0 4px}.intro-card h1{font-family:'Playfair Display',serif;font-size:clamp(40px,5vw,63px);line-height:.98;font-weight:600;letter-spacing:-1.6px;margin:17px 0 15px;color:#fff3e1}.intro-card h1 em{color:#e8bc7d;font-weight:500}.intro-card p{color:#d4beaa;font-size:13px;line-height:1.75;max-width:348px;margin:0 0 22px}.intro-meta{display:flex;gap:13px;padding:14px 0 17px;border-top:1px solid var(--line);font-size:8px;letter-spacing:1px;color:#c5a98e;white-space:nowrap}.primary-button{display:flex;align-items:center;justify-content:space-between;width:100%;padding:14px 17px;background:#c47b52;border:0;color:#fff7e9;font-size:10px;font-weight:700;letter-spacing:1.8px;cursor:pointer;transition:background .2s,transform .2s}.primary-button:hover{background:#d18c5d;transform:translateY(-2px)}.primary-button span{font-size:17px}.mature-note{font-size:9px;color:#a88f7d;text-align:center;margin-top:13px}.cast-panel{position:absolute;z-index:4;right:39px;top:24%;width:260px;padding:18px 17px 12px;background:rgba(37,26,22,.77);border:1px solid rgba(248,222,184,.2);backdrop-filter:blur(8px);box-shadow:0 12px 45px rgba(35,21,15,.2);transition:opacity .3s,transform .3s}.cast-heading{display:flex;justify-content:space-between;font-size:9px;letter-spacing:1.8px;color:#e4c59f;font-weight:700;padding:0 2px 12px}.cast-count{color:#a9907a}.character-card{border:0;border-top:1px solid rgba(255,238,215,.12);background:transparent;width:100%;display:flex;align-items:center;text-align:left;padding:10px 1px;cursor:pointer;gap:10px;transition:background .2s}.character-card:hover{background:rgba(255,230,190,.08)}.portrait{width:37px;height:37px;border-radius:50%;display:grid;place-items:center;flex:none;border:1px solid rgba(255,237,204,.45);font-size:17px}.portrait-ada{background:radial-gradient(circle at 50% 32%,#ddaf87 0 22%,#54342e 23% 43%,#201c20 44% 100%);color:#e9c28d}.portrait-cleo{background:radial-gradient(circle at 50% 32%,#e4b89a 0 22%,#5f5545 23% 44%,#253b39 45% 100%);color:#d8b27b}.portrait-ruby{background:radial-gradient(circle at 50% 32%,#eac39e 0 22%,#8c4c49 23% 44%,#422837 45% 100%);color:#f1ce9b}.character-copy{display:flex;flex-direction:column;gap:4px;min-width:0}.character-copy strong{font-family:'Playfair Display',serif;font-weight:600;font-size:13px;color:#fff0dd;white-space:nowrap}.character-copy small{font-size:8px;color:#b99c82;letter-spacing:1.1px}.card-arrow{margin-left:auto;color:#cf9f69;font-size:14px}.cast-foot{border-top:1px solid rgba(255,238,215,.12);margin-top:4px;padding-top:12px;color:#ad927a;font-size:9px}.cast-foot span{color:#d7907b;margin-right:5px}.location-nav{position:absolute;z-index:4;bottom:38px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:5px;padding:8px;background:rgba(35,24,21,.78);border:1px solid rgba(246,219,182,.2);backdrop-filter:blur(8px)}.nav-caption{font-size:8px;letter-spacing:1.5px;color:#bb9c7d;padding:0 12px 0 8px;white-space:nowrap}.location-button{border:1px solid transparent;background:transparent;display:flex;align-items:center;gap:7px;padding:9px 11px;cursor:pointer;color:#d4b99e;transition:all .2s}.location-button span{font-size:15px}.location-button small{font-size:8px;letter-spacing:1px;white-space:nowrap}.location-button:hover,.location-button.active{background:rgba(198,132,82,.2);border-color:rgba(230,183,120,.35);color:#f4d4a9}.dialogue-wrap{position:absolute;z-index:6;left:50%;bottom:24px;transform:translateX(-50%);width:min(770px,67vw);animation:fadeup .45s ease both}.dialogue-wrap.hidden{display:none}.dialogue-topline{display:flex;align-items:center;justify-content:space-between;color:#efc78e;font-size:8px;letter-spacing:1.7px;font-weight:700;margin-bottom:8px}.dialogue-progress{height:2px;width:96px;background:rgba(255,242,222,.25);display:block}.dialogue-progress i{height:100%;display:block;width:22%;background:#e8bb7a;transition:width .3s}.dialogue-box{background:rgba(38,27,23,.95);border:1px solid rgba(247,220,181,.34);box-shadow:0 14px 50px rgba(22,14,11,.4);padding:21px 26px 19px;backdrop-filter:blur(12px)}.speaker-row{display:flex;align-items:center;gap:11px}.speaker-icon{width:35px;height:35px;border-radius:50%;display:grid;place-items:center;background:#63473a;color:#ecc78e;border:1px solid rgba(245,214,171,.45);font-size:17px}.speaker-name{font-family:'Playfair Display',serif;font-size:17px;font-weight:600;color:#fff0dc}.speaker-role{font-size:8px;letter-spacing:1.4px;color:#bd9d7d;margin-top:3px}.affection{margin-left:auto;font-size:13px;color:#e79583}.affection span{color:#f1d0a6;font-size:10px}.dialogue-box p{font-family:'Playfair Display',serif;font-size:17px;line-height:1.55;color:#f1e1ce;margin:15px 0 17px;max-width:700px}.choice-list{display:grid;grid-template-columns:1fr 1fr;gap:8px}.choice-button{border:1px solid rgba(247,220,181,.24);background:rgba(255,238,215,.045);padding:11px 13px;text-align:left;color:#e7d2bb;cursor:pointer;font-size:11px;line-height:1.4;transition:all .2s}.choice-button:hover{border-color:#d6a86f;background:rgba(210,160,103,.14);color:#fff3e2}.choice-button .choice-num{color:#d4a66f;font-size:9px;letter-spacing:1px;margin-right:8px}.continue-button{border:0;background:transparent;color:#ecc38b;font-size:9px;font-weight:700;letter-spacing:1.7px;cursor:pointer;padding:9px 0 0;float:right}.continue-button span{font-size:15px;margin-left:8px}.bottom-note{position:absolute;z-index:3;bottom:10px;left:40px;right:40px;display:flex;justify-content:space-between